-- =============================================================================================
-- Hand-written below this line: integrity rules, posting, immutability of posted entries,
-- reversals, the period lock, the property currency lock, row-level security and grants.
-- See docs/architecture/DATA_MODEL.md section 6 (Finance ledger).
-- Amounts are bigint minor units. Dates are the property's local calendar dates.
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- ledger_accounts
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "ledger_accounts" ADD CONSTRAINT "ledger_accounts_code_format"
  CHECK ("code" ~ '^[0-9A-Z][0-9A-Z.-]{0,19}$');
ALTER TABLE "ledger_accounts" ADD CONSTRAINT "ledger_accounts_name_trimmed"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 120);
ALTER TABLE "ledger_accounts" ADD CONSTRAINT "ledger_accounts_system_key_format"
  CHECK ("system_key" IS NULL OR "system_key" ~ '^[A-Z][A-Z0-9_]{1,39}$');
ALTER TABLE "ledger_accounts" ADD CONSTRAINT "ledger_accounts_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

-- An account never moves to another property and keeps its system key. Its type is what its
-- history means, so it can change only while nothing has been booked to it.
CREATE FUNCTION app_ledger_account_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."organisation_id" <> OLD."organisation_id" OR NEW."property_id" <> OLD."property_id"
     OR NEW."system_key" IS DISTINCT FROM OLD."system_key" THEN
    RAISE EXCEPTION 'ledger account % cannot move or change its system key', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."type" <> OLD."type" AND EXISTS (
    SELECT 1 FROM "journal_lines" WHERE "account_id" = OLD."id"
  ) THEN
    RAISE EXCEPTION 'ledger account % has entries; its type cannot change', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "ledger_accounts_guard"
  BEFORE UPDATE ON "ledger_accounts"
  FOR EACH ROW EXECUTE FUNCTION app_ledger_account_guard();

-- ---------------------------------------------------------------------------------------------
-- accounting_periods: at most a year long, never overlapping within a property, and never
-- moved. Closing and reopening are status changes; who may reopen is decided by the API
-- (maker-checker, Phase 6 Part 4).
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "accounting_periods" ADD CONSTRAINT "accounting_periods_dates"
  CHECK ("end_date" >= "start_date" AND "end_date" < "start_date" + interval '1 year');
ALTER TABLE "accounting_periods" ADD CONSTRAINT "accounting_periods_close_consistent"
  CHECK (("status" = 'CLOSED') = ("closed_at" IS NOT NULL)
         AND ("closed_by_user_id" IS NULL OR "closed_at" IS NOT NULL));
ALTER TABLE "accounting_periods" ADD CONSTRAINT "accounting_periods_no_overlap"
  EXCLUDE USING gist ("property_id" WITH =, daterange("start_date", "end_date", '[]') WITH &&);

CREATE FUNCTION app_accounting_period_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF (NEW."organisation_id", NEW."property_id", NEW."start_date", NEW."end_date", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."start_date", OLD."end_date", OLD."created_at") THEN
    RAISE EXCEPTION 'accounting period % cannot move or change its dates', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "accounting_periods_guard"
  BEFORE UPDATE ON "accounting_periods"
  FOR EACH ROW EXECUTE FUNCTION app_accounting_period_guard();

-- ---------------------------------------------------------------------------------------------
-- journal_entries
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "journal_entries" ADD CONSTRAINT "journal_entries_description_trimmed"
  CHECK ("description" = btrim("description") AND length("description") BETWEEN 1 AND 500);
ALTER TABLE "journal_entries" ADD CONSTRAINT "journal_entries_currency_format"
  CHECK ("currency" ~ '^[A-Z]{3}$');
-- A reversal says so, and only a reversal points at another entry (never at itself).
ALTER TABLE "journal_entries" ADD CONSTRAINT "journal_entries_reversal_consistent"
  CHECK (("source" = 'REVERSAL') = ("reverses_entry_id" IS NOT NULL)
         AND "reverses_entry_id" IS DISTINCT FROM "id");
-- Posted entries carry their number and posting time; drafts carry neither.
ALTER TABLE "journal_entries" ADD CONSTRAINT "journal_entries_post_consistent"
  CHECK (("status" = 'POSTED') = ("posted_at" IS NOT NULL)
         AND ("status" = 'POSTED') = ("entry_number" IS NOT NULL)
         AND ("posted_by_user_id" IS NULL OR "posted_at" IS NOT NULL)
         AND ("entry_number" IS NULL OR "entry_number" >= 1));

-- Entries are born as drafts: posting is a separate step so that every rule below is checked.
CREATE FUNCTION app_journal_entry_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."status" <> 'DRAFT' THEN
    RAISE EXCEPTION 'journal entries are created as drafts and then posted'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "journal_entries_insert_check"
  BEFORE INSERT ON "journal_entries"
  FOR EACH ROW EXECUTE FUNCTION app_journal_entry_insert_check();

-- Posting (DRAFT -> POSTED) checks, under locks that serialise it with conflicting changes:
--   * the property is not archived and the entry is in the property's currency;
--   * an OPEN accounting period covers the entry date (row lock: a period cannot close while
--     an entry is being posted into it);
--   * at least two lines, debits equal credits;
--   * every account is ACTIVE (row lock against archiving);
--   * a reversal mirrors its posted original line for line and is not dated before it;
-- then stamps posted_at and assigns the next entry number of the property (advisory lock, so
-- numbers have no gaps and no duplicates). A posted entry never changes again.
CREATE FUNCTION app_journal_entry_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  prop record;
  totals record;
  original record;
BEGIN
  IF OLD."status" = 'POSTED' THEN
    RAISE EXCEPTION 'journal entry % is posted and cannot change; reverse it instead', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'journal entry % cannot move or change its creator', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'DRAFT' THEN
    RETURN NEW;
  END IF;

  SELECT "status", "currency" INTO prop FROM "properties" WHERE "id" = NEW."property_id";
  IF prop."status" = 'ARCHIVED' THEN
    RAISE EXCEPTION 'property % is archived; nothing can be posted', NEW."property_id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."currency" <> prop."currency" THEN
    RAISE EXCEPTION 'journal entry % is not in the property currency %', OLD."id", prop."currency"
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM 1 FROM "accounting_periods"
   WHERE "property_id" = NEW."property_id" AND "status" = 'OPEN'
     AND NEW."entry_date" BETWEEN "start_date" AND "end_date"
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no open accounting period covers %', NEW."entry_date"
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) AS n, coalesce(sum("debit_minor"), 0) AS debits, coalesce(sum("credit_minor"), 0) AS credits
    INTO totals FROM "journal_lines" WHERE "entry_id" = NEW."id";
  IF totals.n < 2 OR totals.debits <> totals.credits THEN
    RAISE EXCEPTION 'journal entry % is not balanced (% lines, debits %, credits %)',
      OLD."id", totals.n, totals.debits, totals.credits
      USING ERRCODE = 'check_violation';
  END IF;

  PERFORM 1 FROM "ledger_accounts"
   WHERE "id" IN (SELECT "account_id" FROM "journal_lines" WHERE "entry_id" = NEW."id")
   FOR SHARE;
  IF EXISTS (
    SELECT 1 FROM "journal_lines" l JOIN "ledger_accounts" a ON a."id" = l."account_id"
     WHERE l."entry_id" = NEW."id" AND a."status" <> 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'journal entry % uses an archived account', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW."reverses_entry_id" IS NOT NULL THEN
    SELECT "status", "entry_date" INTO original FROM "journal_entries" WHERE "id" = NEW."reverses_entry_id";
    IF original."status" <> 'POSTED' THEN
      RAISE EXCEPTION 'only a posted entry can be reversed' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."entry_date" < original."entry_date" THEN
      RAISE EXCEPTION 'a reversal cannot be dated before the entry it reverses'
        USING ERRCODE = 'check_violation';
    END IF;
    -- Same lines with debit and credit swapped (as multisets; line order may differ).
    IF EXISTS (
      (SELECT "account_id", "unit_id", "credit_minor", "debit_minor"
         FROM "journal_lines" WHERE "entry_id" = NEW."reverses_entry_id"
       EXCEPT ALL
       SELECT "account_id", "unit_id", "debit_minor", "credit_minor"
         FROM "journal_lines" WHERE "entry_id" = NEW."id")
      UNION ALL
      (SELECT "account_id", "unit_id", "debit_minor", "credit_minor"
         FROM "journal_lines" WHERE "entry_id" = NEW."id"
       EXCEPT ALL
       SELECT "account_id", "unit_id", "credit_minor", "debit_minor"
         FROM "journal_lines" WHERE "entry_id" = NEW."reverses_entry_id")
    ) THEN
      RAISE EXCEPTION 'a reversal must mirror the lines of entry %', NEW."reverses_entry_id"
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.journal_entries:' || NEW."property_id"::text, 0));
  SELECT coalesce(max("entry_number"), 0) + 1 INTO NEW."entry_number"
    FROM "journal_entries" WHERE "property_id" = NEW."property_id";
  NEW."posted_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "journal_entries_guard"
  BEFORE UPDATE ON "journal_entries"
  FOR EACH ROW EXECUTE FUNCTION app_journal_entry_guard();

-- Only drafts may be deleted (their lines first: the line foreign key restricts).
CREATE FUNCTION app_journal_entry_delete_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."status" <> 'DRAFT' THEN
    RAISE EXCEPTION 'journal entry % is posted and cannot be deleted; reverse it instead', OLD."id"
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN OLD;
END
$$;

CREATE TRIGGER "journal_entries_delete_check"
  BEFORE DELETE ON "journal_entries"
  FOR EACH ROW EXECUTE FUNCTION app_journal_entry_delete_check();

-- ---------------------------------------------------------------------------------------------
-- journal_lines: exactly one positive side; changes only while the entry is a draft.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "journal_lines" ADD CONSTRAINT "journal_lines_one_side"
  CHECK ("debit_minor" >= 0 AND "credit_minor" >= 0 AND ("debit_minor" > 0) <> ("credit_minor" > 0));
ALTER TABLE "journal_lines" ADD CONSTRAINT "journal_lines_line_number"
  CHECK ("line_number" >= 1);
ALTER TABLE "journal_lines" ADD CONSTRAINT "journal_lines_description_trimmed"
  CHECK ("description" IS NULL OR ("description" = btrim("description") AND length("description") BETWEEN 1 AND 500));

-- The entry row is share-locked, so a line change and the posting of its entry are serialised:
-- once an entry is posted, no line can be added, changed or removed.
CREATE FUNCTION app_journal_line_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  entry_status "JournalEntryStatus";
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT "status" INTO entry_status FROM "journal_entries" WHERE "id" = OLD."entry_id" FOR SHARE;
    IF entry_status IS DISTINCT FROM 'DRAFT' THEN
      RAISE EXCEPTION 'lines of posted journal entry % cannot change', OLD."entry_id"
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT "status" INTO entry_status FROM "journal_entries" WHERE "id" = NEW."entry_id" FOR SHARE;
    IF entry_status IS DISTINCT FROM 'DRAFT' THEN
      RAISE EXCEPTION 'lines of posted journal entry % cannot change', NEW."entry_id"
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;
  RETURN OLD;
END
$$;

CREATE TRIGGER "journal_lines_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "journal_lines"
  FOR EACH ROW EXECUTE FUNCTION app_journal_line_guard();

-- TRUNCATE skips row triggers: refuse it on the ledger for every role, including the owner.
CREATE FUNCTION app_reject_ledger_truncate() RETURNS trigger
  LANGUAGE plpgsql
  AS $$ BEGIN RAISE EXCEPTION 'the ledger cannot be truncated' USING ERRCODE = 'insufficient_privilege'; END $$;

CREATE TRIGGER "journal_entries_no_truncate"
  BEFORE TRUNCATE ON "journal_entries"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();

CREATE TRIGGER "journal_lines_no_truncate"
  BEFORE TRUNCATE ON "journal_lines"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_ledger_truncate();

-- ---------------------------------------------------------------------------------------------
-- properties: the currency is fixed once the property has any journal entry (draft or posted).
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_property_currency_lock() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."currency" <> OLD."currency"
     AND EXISTS (SELECT 1 FROM "journal_entries" WHERE "property_id" = OLD."id") THEN
    RAISE EXCEPTION 'property % has ledger entries; its currency cannot change', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "properties_currency_lock"
  BEFORE UPDATE OF "currency" ON "properties"
  FOR EACH ROW EXECUTE FUNCTION app_property_currency_lock();

-- ---------------------------------------------------------------------------------------------
-- Row-level security: tenant context only (MULTI_TENANCY section 3.3).
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ledger_accounts', 'accounting_periods', 'journal_entries', 'journal_lines'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['journal_entries', 'journal_lines'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR DELETE USING (organisation_id = app_current_organisation_id())', t || '_delete', t);
  END LOOP;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Least privilege: accounts and periods are never deleted; journal rows only while drafts
-- (enforced by the triggers above).
-- ---------------------------------------------------------------------------------------------
REVOKE ALL ON "ledger_accounts", "accounting_periods", "journal_entries", "journal_lines" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "ledger_accounts", "accounting_periods" TO veyra_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON "journal_entries", "journal_lines" TO veyra_app;
